using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q976–Q1045: batch 19 finale — rivals/chips (schema 31, WIP local).</summary>
public class HatchRivalsChipsFinaleLaterTests
{
    static ModelState R(Game g, int c) => new ModelState { Id = g.State.TakeId(), LineId = "mini", Capability = c, Status = ModelStatus.Released, Alignment = 500, Name = "F19" };
    static void Acq(Game g, LabState r) { r.Models.Add(R(g, 508)); r.Cash = -16_200; r.WeeksInDebt = 1; Finance.Earn(g.Me, LedgerLine.CapitalIn, 88_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); }

    [Fact] public void Q976_finale19_976() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4100, 8)); LabState x = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(x.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acq(g, x); Assert.Equal(31, g.State.Schema); }
    [Fact] public void Q977_finale19_977() { var g = Game.New(seed: 1701); var r = g.Rival("openaye"); r.Models.Add(R(g, 518)); r.Cash = -17_100; Finance.Earn(g.Me, LedgerLine.CapitalIn, 73_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.BuyGpus(r.Id, 1, HardwareBatch.Hq), CommandError.LabAbsorbed); }
    [Fact] public void Q978_finale19_978() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4400, 6)); LabState x = HatchFollowUpLaterTests.OpenAyeBuyer(g, 46_000_000); g.Do(Command.BuyListedChips(x.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acq(g, x); SaveSchemaPretend.AssertRoundTrip(g.Sim); }
    [Fact] public void Q979_finale19_979() { var g = Game.New(seed: 1703); var r = g.Rival("openaye"); r.Models.Add(R(g, 532)); r.Cash = -17_300; Finance.Earn(g.Me, LedgerLine.CapitalIn, 74_000_000); Assert.True(AcquisitionSystem.Quote(g.C, g.State, g.Me, r).Total > 0); }
    [Fact] public void Q980_finale19_980() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4800, 5)); LabState x = HatchFollowUpLaterTests.OpenAyeBuyer(g, 42_000_000); g.Do(Command.BuyListedChips(x.Id, g.Id, d.Id, HardwareBatch.Cloud, 2)); Acq(g, x); Assert.True(LabQueries.ParticipatesInEconomy(g.Me)); }
